import * as THREE from 'three';
import { GLTFLoader, type GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';

/** Entry of public/assets/models/index.json (generated by tools/asset-pipeline). */
interface IndexEntry {
  bytes: number;
  sha256: string;
}

export interface LoadProgress {
  loadedBytes: number;
  totalBytes: number;
  failed: string[];
}

/**
 * Loads the GLB models produced by the asset pipeline.
 *
 * - Progress is reported in real bytes (sizes come from index.json), not a fake timer.
 * - URLs carry the file hash (?v=…), so the server can serve /assets with immutable caching and a
 *   changed model is never served stale.
 * - Each file is fetched at most once per page load; matches reuse the parsed scenes.
 * - Failed files are retried, then reported; callers fall back to procedural models.
 */
export class AssetLoader {
  private index: Record<string, IndexEntry> = {};
  private loader: GLTFLoader;
  private cache = new Map<string, Promise<GLTF | null>>();
  private loaded = new Map<string, GLTF>();
  private bytesDone = new Map<string, number>();
  failed = new Set<string>();

  constructor(private readonly base = '/assets/models/') {
    this.loader = new GLTFLoader();
    this.loader.setMeshoptDecoder(MeshoptDecoder);
  }

  async loadIndex(): Promise<void> {
    if (Object.keys(this.index).length) return;
    const res = await fetch(this.base + 'index.json', { cache: 'no-cache' });
    if (!res.ok) throw new Error(`index.json ${res.status}`);
    const json = (await res.json()) as { files: Record<string, IndexEntry> };
    this.index = json.files;
  }

  /** Loads several files, reporting combined byte progress. Resolves even if some fail. */
  async loadAll(files: string[], onProgress?: (p: LoadProgress) => void): Promise<LoadProgress> {
    await this.loadIndex();
    const total = files.reduce((a, f) => a + (this.index[f]?.bytes ?? 100_000), 0);
    const report = () => {
      const loadedBytes = files.reduce((a, f) => a + (this.bytesDone.get(f) ?? 0), 0);
      onProgress?.({ loadedBytes: Math.min(loadedBytes, total), totalBytes: total, failed: [...this.failed] });
    };
    report();
    await Promise.all(files.map((f) => this.load(f, report)));
    const loadedBytes = files.reduce((a, f) => a + (this.bytesDone.get(f) ?? 0), 0);
    const result = { loadedBytes, totalBytes: total, failed: files.filter((f) => this.failed.has(f)) };
    onProgress?.(result);
    return result;
  }

  load(file: string, onTick?: () => void): Promise<GLTF | null> {
    const existing = this.cache.get(file);
    if (existing) return existing;
    const promise = this.loadWithRetry(file, onTick);
    this.cache.set(file, promise);
    return promise;
  }

  private async loadWithRetry(file: string, onTick?: () => void): Promise<GLTF | null> {
    const entry = this.index[file];
    const url = this.base + file + (entry ? `?v=${entry.sha256.slice(0, 12)}` : '');
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const gltf = await this.loader.loadAsync(url, (ev) => {
          this.bytesDone.set(file, ev.loaded);
          onTick?.();
        });
        this.bytesDone.set(file, entry?.bytes ?? 1);
        this.failed.delete(file);
        this.loaded.set(file, gltf);
        onTick?.();
        return gltf;
      } catch (err) {
        console.warn(`Model ${file} failed (attempt ${attempt + 1})`, err);
        await new Promise((r) => setTimeout(r, 500 * (attempt + 1)));
      }
    }
    this.failed.add(file);
    this.cache.delete(file); // allow a later manual retry
    this.bytesDone.set(file, entry?.bytes ?? 0);
    onTick?.();
    return null;
  }

  get(file: string): GLTF | undefined {
    return this.loaded.get(file);
  }

  /** Finds a named top-level node inside a bundle file. */
  node(file: string, key: string): THREE.Object3D | undefined {
    return this.loaded.get(file)?.scene.getObjectByName(key);
  }
}

export const assets = new AssetLoader();
